$ErrorActionPreference='Stop';$edge='C:\Program Files (x86)\Microsoft\Edge\Application\msedge.exe';$profile=Join-Path $env:TEMP "curdun-v2p1-$Port";$proc=Start-Process $edge -ArgumentList @('--headless','--disable-gpu','--disable-extensions','--no-first-run','--remote-allow-origins=*',"--remote-debugging-port=$Port","--user-data-dir=$profile",'http://localhost:8000/app.html') -WindowStyle Hidden -PassThru;$ws=$null
try{$page=$null;for($i=0;$i-lt60-and!$page;$i++){Start-Sleep -Milliseconds 200;try{foreach($c in (Invoke-RestMethod "http://localhost:$Port/json/list")){if($c.type-eq'page'-and$c.url-like'http://localhost:8000/*'){$page=$c;break}}}catch{}};if(!$page){throw'No page'};$ws=[Net.WebSockets.ClientWebSocket]::new();$ws.ConnectAsync([Uri]$page.webSocketDebuggerUrl,[Threading.CancellationToken]::None).GetAwaiter().GetResult()|Out-Null
$js=@'
(async()=>{const pause=ms=>new Promise(r=>setTimeout(r,ms)),wait=async(fn,l)=>{for(let i=0;i<150;i++){const v=fn();if(v)return v;await pause(100)}throw Error('Timeout '+l)},fill=(el,v)=>{el.value=v;el.dispatchEvent(new Event('input',{bubbles:true}))};fill(await wait(()=>document.querySelector('#login-email'),'login'),'p14-audit-admin@test.local');fill(document.querySelector('#login-pw'),'P14Audit!2026');document.querySelector('#btn-signin').click();await wait(()=>document.querySelector('[data-launch="pos"]'),'workspace');document.querySelector('[data-launch="pos"]').click();await wait(()=>typeof posSetStoreType==='function'&&S.posConfig,'bootstrap');S.view='pos';S.posView='backoffice';const expected={retail:{variants:false,batches:false,serial_numbers:false,tables:false,delivery:false},fashion:{variants:true,batches:false,serial_numbers:false,tables:false,delivery:false},electronics:{variants:false,batches:false,serial_numbers:true,warranties:true,tables:false},bakery_food:{variants:false,batches:true,expiry_tracking:true,serial_numbers:false,tables:false},furniture_home:{variants:true,delivery:true,batches:false,serial_numbers:false,tables:false},restaurant:{tables:true,kitchen_orders:true,order_notes:true,dine_in:true,takeaway:true}};const matrices={},navigation={};try{for(const [type,checks] of Object.entries(expected)){const settings=await posSetStoreType(type);await posBootstrap();if(settings.store_type!==type||S.posStoreType!==type||S.posConfig.store_type!==type)throw Error('Store type did not persist '+type);for(const [key,value] of Object.entries(checks))if(Boolean(settings.store_capabilities[key])!==value||posHasStoreCapability(key)!==value)throw Error(type+' capability '+key);S.posBackofficeTab='dashboard';render();await pause(20);const nav=document.querySelector('.pos-topnav-left')?.innerText||'';if((type==='restaurant')!==nav.includes('Menu Items'))throw Error('Stale navigation for '+type);if(/Variants|Serial Numbers|Warranties|Batches|Kitchen|Deliveries/.test(nav))throw Error('Unimplemented navigation leaked for '+type);navigation[type]=nav.replace(/\s+/g,' ').trim();matrices[type]=settings.store_capabilities}const override=await posSetStoreType('retail',{delivery:true});if(!override.store_capabilities.delivery)throw Error('Safe override failed');const overrideOff=await posSetStoreType('fashion',{variants:false});if(overrideOff.store_capabilities.variants||posHasStoreCapability('variants'))throw Error('Explicit OFF failed');S.posBackofficeTab='config-settings';render();await pause(20);const settingsText=document.querySelector('#pos-store-features')?.innerText||'';if(!settingsText.includes('Store Features')||!settingsText.includes('Explicit Off')||!settingsText.includes('Planned V2-P4'))throw Error('Settings provenance UI failed');let invalidType=0,invalidCapability=0;try{await posSetStoreType('unknown')}catch(e){invalidType=e.status||0}try{await posSetStoreType('retail',{made_up:true})}catch(e){invalidCapability=e.status||0}if(invalidType!==422||invalidCapability!==422)throw Error('Invalid input was not rejected');const session32=await posApiFetch('/pos/sessions/32/summary');if(session32.session.state!=='CLOSED'||Number(session32.expected_cash)!==258.93||Number(session32.cash_reconciliation.counted_cash)!==258.93||Number(session32.cash_reconciliation.difference)!==0)throw Error('Session 32 changed');return{matrices,navigation,overrideOn:override.store_capabilities.delivery,overrideOff:overrideOff.store_capabilities.variants,settingsProvenance:true,invalidType,invalidCapability,session32:{state:session32.session.state,expected:Number(session32.expected_cash),counted:Number(session32.cash_reconciliation.counted_cash),difference:Number(session32.cash_reconciliation.difference)}}}finally{await posSetStoreType('retail',{})}})()
'@;$m=@{id=1;method='Runtime.evaluate';params=@{expression=$js;awaitPromise=$true;returnByValue=$true}}|ConvertTo-Json -Depth 8 -Compress;$bytes=[Text.Encoding]::UTF8.GetBytes($m);$ws.SendAsync([ArraySegment[byte]]::new($bytes),[Net.WebSockets.WebSocketMessageType]::Text,$true,[Threading.CancellationToken]::None).GetAwaiter().GetResult()|Out-Null;while(1){$buf=New-Object byte[] 1048576;$x=$ws.ReceiveAsync([ArraySegment[byte]]::new($buf),[Threading.CancellationToken]::None).GetAwaiter().GetResult();$r=([Text.Encoding]::UTF8.GetString($buf,0,$x.Count)|ConvertFrom-Json);if($r.id-eq1){if($r.result.exceptionDetails){throw($r.result.exceptionDetails|ConvertTo-Json -Depth 12)};$r.result.result.value|ConvertTo-Json -Depth 20;break}}}finally{if($ws){$ws.Dispose()};if($proc-and!$proc.HasExited){Stop-Process $proc.Id -Force}}
